const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const brand = typeof $json.brand === 'string' ? $json.brand.trim().toLowerCase() : '';
const listName = typeof $json.listName === 'string' ? $json.listName.trim() : '';
const campaignId = typeof $json.campaignId === 'string' ? $json.campaignId.trim() : '';
const rawLimit = typeof $json.limit === 'string' ? $json.limit.trim() : '';
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let error = null;
if (!uuid.test(sessionId)) {
  error = { code: 'INVALID_SESSION', message: 'This tool needs a valid conversation session.' };
} else if (brand !== 'oddtoe' && brand !== 'datalabs') {
  error = { code: 'INVALID_BRAND', message: 'Say which brand to draft for: oddtoe or datalabs.' };
} else if (rawLimit !== '' && !/^[0-9]{1,3}$/.test(rawLimit)) {
  error = { code: 'INVALID_LIMIT', message: 'The limit must be a whole number of prospects.' };
}
return { json: { valid: error === null, sessionId, brand, listName, campaignId, limit: rawLimit,
  proposedInput: { brand, listName, campaignId, limit: rawLimit },
  ...(error ? { response: { ok: false, error } } : {}) } };

const input = $('Validate Draftable Input').first().json;
const body = $json;
if (body?.schemaVersion !== 1) {
  const message = typeof body?.error?.message === 'string' ? body.error.message
    : 'The prospect store did not answer.';
  const code = body?.error?.code === 'OUTREACH_NOT_CONFIGURED'
    ? 'OUTREACH_NOT_CONFIGURED' : 'DRAFTABLE_UNAVAILABLE';
  return [{ json: { ...input, response: { ok: false, error: { code, message } } } }];
}
const eligible = (body.eligible ?? []).map((entry) => ({
  prospectId: entry.prospect.prospectId,
  company: entry.prospect.company,
  contactName: entry.prospect.contactName,
  contactEmail: entry.prospect.contactEmail,
  website: entry.prospect.website,
  region: entry.prospect.region,
  tier: entry.prospect.tier,
  status: entry.prospect.status,
  notes: entry.prospect.notes,
  outreachUrl: entry.outreachUrl,
  warning: entry.warning
}));
return [{ json: { ...input, response: { ok: true,
  brand: body.brand,
  sender: { name: body.settings.senderName, contact: body.settings.senderContact },
  unsubscribeLine: body.settings.unsubscribeLine,
  campaign: body.campaign ? { campaignId: body.campaign.campaignId, name: body.campaign.name,
    offer: body.campaign.brief.offer } : null,
  dailyCap: body.dailyCap, draftedToday: body.draftedToday, remainingToday: body.remainingToday,
  eligible, eligibleCount: eligible.length,
  skipped: body.skipped, skippedCount: (body.skipped ?? []).length,
  guidance: eligible.length === 0
    ? 'Nobody is draftable right now. Read the skipped list aloud with its reasons; do not draft anyone who is not in eligible.'
    : 'Compose one email per eligible prospect. Every body MUST contain the unsubscribe line and the sender name verbatim, and the prospect\'s own outreachUrl. Then call create_outreach_drafts. Never email anyone who is not in this eligible list.'
} } }];

const response = $json.response;
const error = response?.ok === false ? String(response.error?.message ?? 'Tool failed') : '';
return { json: { occurredAt: new Date().toISOString(),
  sessionId: String($json.sessionId ?? ''), requestId: '',
  toolName: 'list_draftable_prospects',
  proposedInput: JSON.stringify($json.proposedInput ?? {}),
  result: JSON.stringify(response), error, response } };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
